        if not os.path.exists(f):
            return (False, f"Missing predicted output file: {f}")

    # Check PNG is a valid image (non-empty with PNG header)
    with open(pred_png, "rb") as <local-path>        header = f.read(8)
    if len(header) < 8 or header[:4] != b'\x89PNG':
