    if pred_data.ndim != 2 or pred_data.shape[0] != 2:
        return (False, f"Predicted text file has shape {pred_data.shape}, expected (2, N) with 2 rows")

    n_snr = pred_data.shape[1]
    if n_snr < 10 or n_snr > 20:
        return (False, f"Predicted text file has {n_snr} SNR levels, expected around 16")

    pred_snr = pred_data[0]
    pred_acc = pred_data[1]

    # Check SNR values match expected range (-10 to 20 in 2dB steps = 16 values)
    expected_snr = np.arange(-10, 21, 2, dtype=float)
    if len(pred_snr) != len(expected_snr):
        return (False, f"Predicted SNR has {len(pred_snr)} values, expected {len(expected_snr)}")

    if not np.allclose(pred_snr, expected_snr, atol=1e-3):
        return (False, f"Predicted SNR values do not match expected range [-10, -8, ..., 20]. Got: {pred_snr}")

    # Check accuracy values are in valid range [0, 1]
    if np.any(pred_acc < 0) or np.any(pred_acc > 1):
        return (False, f"Predicted accuracy values are outside valid range [0, 1]. Got: {pred_acc}")

    # Compute expected accuracy values directly from the confusion matrix data
    confusion_matrix_path = None
    candidate_paths = [
        'benchmark/datasets/Automatic-Modulation-Classification/Part6_CNN with Transfer Learning on AMC/2_finetune_conv1+conv2+nn/100/pred_confusion_mat_L100.npy',
        'benchmark/datasets/Automatic-Modulation-Classification/Part6_CNN with Transfer Learning on AMC/pred_confusion_mat_L100.npy',
    ]

    # Search for the confusion matrix file
    base_dir = 'benchmark/datasets/Automatic-Modulation-Classification/Part6_CNN with Transfer Learning on AMC/'
    if os.path.exists(base_dir):
        for root, dirs, files in os.walk(base_dir):
            for fname in files:
                if fname == 'pred_confusion_mat_L100.npy':
                    confusion_matrix_path = os.path.join(root, fname)
                    break
            if confusion_matrix_path:
                break

    if confusion_matrix_path is None:
        # Try candidate paths
        for path in candidate_paths:
            if os.path.exists(path):
                confusion_matrix_path = path
                break

    if confusion_matrix_path is not None:
        try:
            confusion_matrices = np.load(confusion_matrix_path, allow_pickle=True)

            # Calculate expected accuracy for each SNR level
            expected_accuracies = []
            for matrix in confusion_matrices:
                diag_sum = np.trace(matrix)
                total_samples = np.sum(matrix)
                if total_samples > 0:
                    accuracy = diag_sum / total_samples
                else:
                    accuracy = 0.0
                expected_accuracies.append(accuracy)

            expected_accuracies = np.array(expected_accuracies)

            if len(expected_accuracies) != len(pred_acc):
                return (False, f"Number of accuracy values ({len(pred_acc)}) doesn't match expected ({len(expected_accuracies)})")

            # Compare accuracy values against computed expected values
            if not np.allclose(pred_acc, expected_accuracies, atol=1e-4):
                max_diff = np.max(np.abs(pred_acc - expected_accuracies))
                return (False, f"Accuracy values differ from expected. Max difference: {max_diff:.6f}. "
                               f"Expected: {expected_accuracies}, Got: {pred_acc}")

            # Check that accuracy generally increases with SNR (reasonable sanity check)
            # Allow some noise but overall trend should be positive
            low_snr_acc = np.mean(pred_acc[:4])   # -10 to -4 dB
            high_snr_acc = np.mean(pred_acc[-4:])  # 14 to 20 dB
            if high_snr_acc < low_snr_acc - 0.1:
                return (False, f"Accuracy does not generally increase with SNR. "
                               f"Low SNR avg: {low_snr_acc:.4f}, High SNR avg: {high_snr_acc:.4f}")

        except Exception as <local-path>            # If we can't load the confusion matrix, fall back to basic checks
            # Just verify the accuracy values are reasonable
            if np.mean(pred_acc[-4:]) < 0.3:
                return (False, f"High SNR accuracy seems too low: {np.mean(pred_acc[-4:]):.4f}")
    else:
        # No confusion matrix available; just do basic sanity checks
        # Check that accuracy is in valid range
        if np.any(pred_acc < 0) or np.any(pred_acc > 1):
            return (False, "Accuracy values outside [0, 1]")

        # Check that accuracy generally increases with SNR
        low_snr_acc = np.mean(pred_acc[:4])
        high_snr_acc = np.mean(pred_acc[-4:])
        if high_snr_acc < low_snr_acc - 0.1:
            return (False, f"Accuracy does not generally increase with SNR. "
                           f"Low SNR avg: {low_snr_acc:.4f}, High SNR avg: {high_snr_acc:.4f}")

    return (True, "All checks passed: files exist, SNR values correct, accuracy values match expected values within tolerance")


