import numpy as np
import os
from PIL import Image


def eval():
    pred_dir = "pred_results"
    gold_dir = "./gold_results/"

    pred_txt = os.path.join(pred_dir, "pred_plot_acc.txt")
    pred_png = os.path.join(pred_dir, "pred_plot_acc_L100.png")
    gold_txt = os.path.join(gold_dir, "pred_plot_acc.txt")
    gold_png = os.path.join(gold_dir, "pred_plot_acc_L100.png")

    # Step 1: Check that predicted output files exist
    if not os.path.exists(pred_txt):
        return (False, f"Missing predicted text file: {pred_txt}")
    if not os.path.exists(pred_png):
        return (False, f"Missing predicted plot file: {pred_png}")

    # Step 2: Check that gold files exist
    if not os.path.exists(gold_txt):
        return (False, f"Missing gold text file: {gold_txt}")
    if not os.path.exists(gold_png):
        return (False, f"Missing gold plot file: {gold_png}")

    # Step 3: Load and validate text file content
    try:
        pred_data = np.loadtxt(pred_txt)
    except Exception as <local-path>        return (False, f"Failed to parse predicted text file: {e}")

    try:
        gold_data = np.loadtxt(gold_txt)
    except Exception as <local-path>        return (False, f"Failed to parse gold text file: {e}")

    # The gold format is a 2xN array: row 0 = SNR, row 1 = accuracy
    # But models might save as Nx2 (transposed). Handle both.
    if pred_data.ndim == 1:
        return (False, f"Predicted text file has only 1 dimension, expected 2D array with SNR and accuracy data")

    # Normalize to 2xN format (row 0 = SNR, row 1 = accuracy)
    if pred_data.shape[0] == 2:
        pred_snr = pred_data[0]
        pred_acc = pred_data[1]
    elif pred_data.shape[1] == 2:
        pred_snr = pred_data[:, 0]
        pred_acc = pred_data[:, 1]
    else:
        return (False, f"Predicted text data has unexpected shape {pred_data.shape}, expected (2, 16) or (16, 2)")

    if gold_data.shape[0] == 2:
        gold_snr = gold_data[0]
        gold_acc = gold_data[1]
    elif gold_data.shape[1] == 2:
        gold_snr = gold_data[:, 0]
        gold_acc = gold_data[:, 1]
    else:
        return (False, f"Gold text data has unexpected shape {gold_data.shape}")

    # Step 4: Validate number of data points
    if len(pred_snr) != 16:
        return (False, f"Expected 16 SNR data points, got {len(pred_snr)}")

    # Step 5: Validate SNR values match expected sequence
    expected_snr = np.arange(-10, 22, 2, dtype=float)
    if not np.allclose(pred_snr, expected_snr, atol=0.5):
        return (False, f"SNR values do not match expected range [-10, -8, ..., 18, 20]. Got: {pred_snr}")

    # Step 6: Validate accuracy values are in valid range
    if np.any(pred_acc < 0) or np.any(pred_acc > 1.0):
        return (False, f"Accuracy values out of range [0, 1]: min={pred_acc.min()}, max={pred_acc.max()}")

    # Step 7: Compare predicted accuracy to gold accuracy
    if not np.allclose(pred_acc, gold_acc, atol=0.02):
        max_diff = np.max(np.abs(pred_acc - gold_acc))
        return (False, f"Accuracy values differ from gold standard. Max difference: {max_diff:.6f} (threshold: 0.02)")

    # Step 8: Validate PNG file
    try:
        img = Image.open(pred_png)
        width, height = img.size
        if width < 200 or height < 200:
            return (False, f"Plot image too small: {width}x{height} pixels")
        # Check it's not blank by looking at pixel variance
        img_array = np.array(img)
        if img_array.std() < 1.0:
            return (False, "Plot image appears to be blank (very low pixel variance)")
    except Exception as <local-path>        return (False, f"Failed to open predicted plot as image: {e}")

    return (True, "All checks passed: 16 SNR-accuracy pairs match gold standard within tolerance, plot file is valid.")


